head.script:
scwin.isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    if (scwin.isIE() && ((scwin.isIE() == 9) || (scwin.isIE() == 10))) {
        // is IE9 or IE10
        scwin.simulateWrapper('#inputCalendar1_input', 'key-sequence', {
            sequence: '20170101'
        });
        WebSquare.wUnit.getDomById('input1').focus()
    } else {
        // is IE 11 and later or not IE
        scwin.simulateWrapper('#inputCalendar1_input', 'key-sequence', {
            sequence: '20170101'
        });
    }
}
scwin.setSimulate2 = function() {
    if (scwin.isIE() && scwin.isIE() <= 10) {
        // is IE version less than 11
        scwin.simulateWrapper('#input1', 'key-sequence', {
            sequence: 'aaa'
        })
        WebSquare.wUnit.getObjById('inputCalendar1_input').focus()
    } else {
        // is IE 11 and later or not IE
        scwin.simulateWrapper('#input1', 'key-sequence', {
            sequence: 'aaa'
        })
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플 실행 후 inputCalendar에 날짜 8자리를 입력한다.
    //1. After running the sample, enter the 8-digit date in inputCalendar.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_input').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 8번째 자리 입력 후 Focus가 inputbox로 이동되어 보여진다.
    //1. After entering the 8th digit, the focus moves to the input box.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#input1').hasClass('w2input_focus')", "true");
    WebSquare.wUnit.addCommand("pause", "5500");
    //Test step 2. inputbox에 3자리를 입력한다.
    //2. Enter three digits in the input box.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 3번째 자리 입력 후 Focus가 inputCalendar로 이동되어 보여진다.
    //2. After inputting 3rd digit, Focus is moved to inputCalendar.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar1_input').hasClass('w2inputCalendar_focus')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 09-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
